settings.game_pad_stick_x_formula:
var m:= 0;

if (continued_movement == false) {
  m := delta_magnitude * 300 * pow(absolute_magnitude, 1);
} else if (absolute_magnitude < 1.5) {
  m := absolute_magnitude * 13;
} else if (absolute_magnitude < 2) {
  m := absolute_magnitude * 24;
} else {
  m := absolute_magnitude * 40;
};

cos(radian) * m;

settings.game_pad_stick_y_formula:
var m:= 0;

if (continued_movement == false) {
  m := delta_magnitude * 300 * pow(absolute_magnitude, 1);
} else if (absolute_magnitude < 1.5) {
  m := absolute_magnitude * 13;
} else if (absolute_magnitude < 2) {
  m := absolute_magnitude * 24;
} else {
  m := absolute_magnitude * 40;
};

sin(radian) * m;

settings.game_pad_stick_vertical_wheel_formula:
var m := 0;

if (abs(cos(radian)) < abs(sin(radian))) {
  if (continued_movement == false) {
    m := delta_magnitude * 1.0;
  } else {
    m := absolute_magnitude * 0.15;
  };
};

sin(radian) * m;

settings.game_pad_stick_horizontal_wheel_formula:
